package io.github.chronicle.core.server;

import com.google.gson.*;
import io.github.chronicle.core.books.BookConfig;
import io.github.chronicle.core.menu.EncounterEditorForm;

import java.nio.charset.StandardCharsets;
import java.util.*;

/** Strict bounded network codec for an incomplete encounter editor draft. */
public final class EncounterEditorJson {
    private static final int MAX_BYTES=64*1024;
    private static final Set<String> FIELDS=Set.of("groupRegistryRevision","bindingRegistryRevision","id","label","description","members","targetKind","siteId","siteLabel","siteRevision","current","problem","creating");
    private static final Set<String> MEMBER_FIELDS=Set.of("entityType","label","count","current","problem");
    private EncounterEditorJson(){ }
    static String encode(EncounterEditorForm form){JsonObject value=new JsonObject();value.addProperty("groupRegistryRevision",form.groupRegistryRevision());value.addProperty("bindingRegistryRevision",form.bindingRegistryRevision());value.addProperty("id",form.id());value.addProperty("label",form.label());value.addProperty("description",form.description());JsonArray members=new JsonArray();for(var member:form.members()){JsonObject row=new JsonObject();row.addProperty("entityType",member.entityType());row.addProperty("label",member.label());row.addProperty("count",member.count());row.addProperty("current",member.current());row.addProperty("problem",member.problem());members.add(row);}value.add("members",members);value.addProperty("targetKind",form.targetKind());value.addProperty("siteId",form.siteId());value.addProperty("siteLabel",form.siteLabel());value.addProperty("siteRevision",form.siteRevision());value.addProperty("current",form.current());value.addProperty("problem",form.problem());value.addProperty("creating",form.creating());String encoded=value.toString();bounded(encoded);return encoded;}
    static EncounterEditorForm decode(String encoded){bounded(encoded);JsonObject value=BookConfig.strictObject(encoded);exact(value,FIELDS,"encounter editor");JsonArray rows=array(required(value,"members"),"members");if(rows.size()>16)throw new IllegalArgumentException("too many encounter member types");List<EncounterEditorForm.Member> members=new ArrayList<>();for(JsonElement element:rows){JsonObject row=object(element,"member");exact(row,MEMBER_FIELDS,"member");members.add(new EncounterEditorForm.Member(string(row,"entityType"),string(row,"label"),integer(row,"count"),bool(row,"current"),string(row,"problem")));}return new EncounterEditorForm(number(value,"groupRegistryRevision"),number(value,"bindingRegistryRevision"),string(value,"id"),string(value,"label"),string(value,"description"),members,string(value,"targetKind"),string(value,"siteId"),string(value,"siteLabel"),number(value,"siteRevision"),bool(value,"current"),string(value,"problem"),bool(value,"creating"));}
    private static void bounded(String value){if(value==null||value.getBytes(StandardCharsets.UTF_8).length>MAX_BYTES)throw new IllegalArgumentException("encounter editor JSON exceeds 64 KiB");}private static void exact(JsonObject value,Set<String>fields,String name){if(!value.keySet().equals(fields))throw new IllegalArgumentException(name+" fields do not match schema");}private static JsonElement required(JsonObject value,String field){if(!value.has(field)||value.get(field).isJsonNull())throw new IllegalArgumentException("missing "+field);return value.get(field);}private static JsonObject object(JsonElement value,String name){if(!value.isJsonObject())throw new IllegalArgumentException(name+" must be an object");return value.getAsJsonObject();}private static JsonArray array(JsonElement value,String name){if(!value.isJsonArray())throw new IllegalArgumentException(name+" must be an array");return value.getAsJsonArray();}private static String string(JsonObject value,String field){JsonElement element=required(value,field);if(!element.isJsonPrimitive()||!element.getAsJsonPrimitive().isString())throw new IllegalArgumentException(field+" must be a string");return element.getAsString();}private static long number(JsonObject value,String field){JsonElement element=required(value,field);if(!element.isJsonPrimitive()||!element.getAsJsonPrimitive().isNumber()||!element.getAsString().matches("-?(0|[1-9][0-9]*)"))throw new IllegalArgumentException(field+" must be an integer");try{return Long.parseLong(element.getAsString());}catch(NumberFormatException failure){throw new IllegalArgumentException(field+" outside long range",failure);}}private static int integer(JsonObject value,String field){long result=number(value,field);if(result<Integer.MIN_VALUE||result>Integer.MAX_VALUE)throw new IllegalArgumentException(field+" outside int range");return(int)result;}private static boolean bool(JsonObject value,String field){JsonElement element=required(value,field);if(!element.isJsonPrimitive()||!element.getAsJsonPrimitive().isBoolean())throw new IllegalArgumentException(field+" must be boolean");return element.getAsBoolean();}
}
